const v = $input.first().json.body;
if (!v || !Array.isArray(v.candidatas) || v.candidatas.length < 1 || v.candidatas.length > 50 || !v.criterios || typeof v.criterios !== 'object' || Array.isArray(v.criterios)) throw new Error('Pedido inválido');
for (const k of ['pedido_id','execucao_id','lote_id']) if (!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v[k])) throw new Error('Identidade inválida');
if (!Number.isSafeInteger(v.revisao) || v.revisao < 1 || !/^[0-9a-f]{64}$/.test(v.snapshot_sha256)) throw new Error('Snapshot inválido');
const c=v.criterios, listas={tipos:['varejista','atacadista','distribuidor','fabricante'],site:['com','sem'],email:['com','sem'],telefone:['whatsapp','fixo']};
const textos=['termos','produtos','excluir','prioridades','observacoes'];
const chaves=[...textos,...Object.keys(listas),'atendimento','situacao','nota','avaliacoes'];
if (Object.keys(c).length!==chaves.length || Object.keys(c).some(k=>!chaves.includes(k))) throw new Error('Critérios inválidos');
for(const k of textos) if(typeof c[k]!=='string'||Array.from(c[k]).length>2000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/.test(c[k])) throw new Error('Texto inválido');
for(const [k,opcoes] of Object.entries(listas)) if(!Array.isArray(c[k])||c[k].some(x=>!opcoes.includes(x))||new Set(c[k]).size!==c[k].length) throw new Error('Opção inválida');
if(!['','priorizar_fisica','fisica','online','ambos'].includes(c.atendimento)||!['','priorizar_funcionamento','funcionamento','excluir_encerradas','excluir_fechadas'].includes(c.situacao)
 || (c.nota!==null&&(!Number.isFinite(c.nota)||c.nota<0||c.nota>5)) || (c.avaliacoes!==null&&(!Number.isSafeInteger(c.avaliacoes)||c.avaliacoes<0))) throw new Error('Critério inválido');
const ids=v.candidatas.map(e=>e&&typeof e==='object'&&(e.google_place_id||e.cnpj&&'cnpj:'+e.cnpj));
if(ids.some(id=>typeof id!=='string'||!id.trim()||id.length>255)||new Set(ids).size!==ids.length) throw new Error('Candidata inválida ou repetida');
const etapas=[];
if(c.nota!==null||c.avaliacoes!==null||(c.situacao&&c.situacao!=='priorizar_funcionamento')) etapas.push('dados_google');
if(c.site.length===1||c.email.length===1) etapas.push('presenca_digital');
if(c.produtos||c.tipos.length||c.excluir||c.observacoes||(c.atendimento&&c.atendimento!=='priorizar_fisica')) etapas.push('perfil_comercial');
if(c.telefone.includes('whatsapp')) etapas.push('whatsapp');
if(c.telefone.includes('fixo')) etapas.push('fixo');
return [{json:{pedido_id:v.pedido_id,execucao_id:v.execucao_id,lote_id:v.lote_id,revisao:v.revisao,snapshot_sha256:v.snapshot_sha256,criterios:c,candidatas:v.candidatas,verificacoes_requeridas:etapas,evidencias:[],pendencias:[]}}];

const v=$input.first().json, c=v.criterios;
for (const e of v.candidatas) {
 const id=e.google_place_id||('cnpj:'+e.cnpj), b=e.dados_brutos||{}, fonte=e.link_maps||b.link||'coleta_google';
 const ev=(criterio,opcao,estado,motivo)=>v.evidencias.push({candidata:id,criterio,opcao:String(opcao),estado,motivo,fonte,horario:new Date().toISOString()});
 for(const [k,campo] of [['nota','review_rating'],['avaliacoes','review_count']]) if(c[k]!==null) {
  const raw=b[campo]; const n=raw!==undefined&&raw!==null&&String(raw).trim()!==''?Number(raw):NaN;
  ev(k,c[k],Number.isFinite(n)?(n>=c[k]?'aprovado':'reprovado'):'nao_confirmado',Number.isFinite(n)?'Valor publicado no Google.':'Valor não confirmado pela origem.');
 }
 if(c.situacao&&c.situacao!=='priorizar_funcionamento') {
  const s=String(e.situacao_google||b.status||'').toLowerCase();
  const aberto=['operational','open','em funcionamento'].includes(s), temp=['temporarily_closed','temporarily closed'].includes(s), encerrado=['permanently_closed','permanently closed','closed_permanently'].includes(s);
  const conhecido=aberto||temp||encerrado;
  const ok=c.situacao==='excluir_encerradas'?!encerrado:aberto;
  ev('situacao',c.situacao,conhecido?(ok?'aprovado':'reprovado'):'nao_confirmado','Situação informada pela origem Google.');
 }
}
return [{json:v}];

const v=$input.first().json, c=v.criterios;
for(const e of v.candidatas) {
 const id=e.google_place_id||('cnpj:'+e.cnpj);
 const ev=(criterio,opcao,estado,motivo)=>v.evidencias.push({candidata:id,criterio,opcao,estado,motivo,fonte:e.link_maps||'coleta_google',horario:new Date().toISOString()});
 for(const k of ['site','email']) if(c[k].length===1) {
  const opcao=c[k][0], valor=e[k];
  let presente=k==='email'?/^[^\s@]+@[^\s@]+$/.test(String(valor||'')):false;
  if(k==='site'&&valor) { try {
   const u=String(valor).match(/^https?:\/\/([a-z0-9-]+(?:\.[a-z0-9-]+)+)(?::[0-9]{1,5})?(?:[/?#][^\s]*)?$/i), host=u?u[1].toLowerCase():'';
   const terceiros=['instagram.com','facebook.com','fb.com','linkedin.com','google.com','google.com.br','goo.gl','whatsapp.com','wa.me','linktr.ee','youtube.com','youtu.be','tiktok.com'];
   presente=Boolean(u)&&!terceiros.some(h=>host===h||host.endsWith('.'+h));
  } catch {} }
  if(presente) ev(k,opcao,opcao==='com'?'aprovado':'reprovado','Contato publicado na coleta Google.');
  else v.pendencias.push({candidata:id,criterio:k,opcao});
 }
 for(const k of ['produtos','excluir','observacoes']) if(c[k]) v.pendencias.push({candidata:id,criterio:k,opcao:c[k]});
 for(const opcao of c.tipos) v.pendencias.push({candidata:id,criterio:'tipos',opcao});
 if(c.atendimento&&c.atendimento!=='priorizar_fisica') v.pendencias.push({candidata:id,criterio:'atendimento',opcao:c.atendimento});
}
v.qualificador_ativo=false;
return [{json:v}];

const v=$('Preparar presença e perfil').first().json, r=$input.first().json;
for(const k of ['pedido_id','execucao_id','lote_id','revisao','snapshot_sha256']) if(r[k]!==v[k]) throw new Error('Resposta de qualificação divergente');
if(!Array.isArray(r.evidencias)) throw new Error('Qualificação sem evidências');
v.evidencias.push(...r.evidencias);
return [{json:v}];

const v=$input.first().json;
v.numeros_whatsapp=[];
if(v.verificacoes_requeridas.includes('whatsapp')) for(const e of v.candidatas) {
 if(/^[0-9]{10,11}$/.test(e.telefone||'')) v.numeros_whatsapp.push('55'+e.telefone);
 else v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'whatsapp',estado:'reprovado',motivo:'Número não informado ou sem formato válido na coleta.',fonte:'coleta_google',horario:new Date().toISOString()});
}
v.numeros_whatsapp=[...new Set(v.numeros_whatsapp)];
return [{json:v}];

const v=$('Preparar WhatsApp').first().json, envelope=$input.first().json;
if(envelope.success!==true||Object.hasOwn(envelope,'error')||!Array.isArray(envelope.data)) throw new Error('Resposta WhatsApp não confirmada');
const respostas=envelope.data;
if(respostas.some(r=>!r||typeof r.exists!=='boolean'||typeof r.number!=='string')||new Set(respostas.map(r=>r.number)).size!==respostas.length) throw new Error('Resposta WhatsApp inválida ou ambígua');
for(const e of v.candidatas) if(/^[0-9]{10,11}$/.test(e.telefone||'')) {
 const r=respostas.find(r=>r.number==='55'+e.telefone);
 v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'whatsapp',contato:e.telefone,estado:r?(r.exists?'aprovado':'reprovado'):'nao_confirmado',motivo:r?'Consulta de registro no WhatsApp.':'Número sem confirmação no retorno.',fonte:'evolution_api',horario:new Date().toISOString()});
}
return [{json:v}];

const v=$input.first().json;
for(const e of v.candidatas) v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'fixo',contato:e.telefone||'',estado:/^[0-9]{2}[2-5][0-9]{7}$/.test(e.telefone||'')?'aprovado':'reprovado',motivo:'Formato de telefone fixo brasileiro conferido.',fonte:'coleta_google',horario:new Date().toISOString()});
return [{json:v}];

const b=$input.first().json.body;
const planilha='17uQ8KmuboL808cvb9M9piIhZwCfHYDJRJ5uw2bUAxvU',aba=10151006;
const erro=()=>{throw new Error('Planejamento precisa de conferência.');};
const uuid=v=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
if(!b||typeof b!=='object'||Array.isArray(b)||Buffer.byteLength(JSON.stringify(b),'utf8')>128000||b.protocolo!==1||b.planilha_id!==planilha||b.aba_id!==aba||!['conferir','sincronizar'].includes(b.operacao))erro();
const c={...b,base:'https://sheets.googleapis.com/v4/spreadsheets/'+planilha,cabecalho:["Pedido ID","Revisão","Vendedor ID","Vendedor","Data","Dia da semana","Nicho","Bairro","Cidade","UF","Situação","Atualizado em","Versão","Critérios de busca"]};
if(b.operacao==='sincronizar'){
 const linha=v=>Array.isArray(v)&&[13,14].includes(v.length)&&v.every(x=>typeof x==='string')&&v[0]===b.pedido_id;
 if(!uuid(b.pedido_id)||!uuid(b.envio_id)||!Number.isInteger(b.linha)||b.linha<2||b.linha>200000||!Number.isSafeInteger(b.revisao)||b.revisao<1||!Number.isSafeInteger(b.versao)||b.versao<1||!linha(b.celulas)||b.celulas[1]!==String(b.revisao)||b.celulas[12]!==String(b.versao)||!Array.isArray(b.anteriores)||!b.anteriores.every(linha))erro();
 c.intervalo="'Planejamento CRM'!A"+b.linha+':'+(b.celulas.length===14?'N':'M')+b.linha;
 c.leitura="'Planejamento CRM'!A"+b.linha+':N'+b.linha;
}
return [{json:c}];

const c=$('Planilha · Preparar').first().json,m=$input.first().json;
if(m.spreadsheetId!==c.planilha_id||!Array.isArray(m.sheets))throw new Error('Arquivo divergente.');
const a=m.sheets.find(s=>s&&s.properties&&s.properties.sheetId===c.aba_id);
const g=a&&a.properties.gridProperties;
if(!a||a.properties.title!=='Planejamento CRM'||!g||!Number.isInteger(g.rowCount)||g.rowCount<1||g.columnCount<14)throw new Error('Aba divergente.');
return [{json:{...c,expandir:c.operacao==='sincronizar'&&g.rowCount<c.linha,ampliar:Math.max(0,(c.linha||0)-g.rowCount)}}];

const c=$('Planilha · Conferir destino').first().json,r=$input.first().json;
if(JSON.stringify(r.values)!==JSON.stringify([c.cabecalho]))throw new Error('Cabeçalho divergente.');
return [{json:c}];

const c=$('Planilha · Validar cabeçalho').first().json;
function lerCelulas(m,c){
 const erro=()=>{throw new Error('Linha precisa de conferência; preserve conteúdo manual.');};
 if(!m||m.spreadsheetId!==c.planilha_id||!Array.isArray(m.sheets))erro();
 const abas=m.sheets.filter(s=>s&&s.properties&&s.properties.sheetId===c.aba_id);
 if(abas.length!==1||abas[0].properties.title!=='Planejamento CRM'||!Array.isArray(abas[0].data)||abas[0].data.length!==1)erro();
 const g=abas[0].data[0];
 if(!g||(g.startRow||0)!==c.linha-1||(g.startColumn||0)!==0)erro();
 const rows=g.rowData===undefined?[]:g.rowData;
 if(!Array.isArray(rows)||rows.length>1||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))erro();
 const cells=rows[0]?.values===undefined?[]:rows[0].values;
 if(!Array.isArray(cells)||cells.length>14)erro();
 return cells.map(cell=>{
  if(!cell||typeof cell!=='object'||Array.isArray(cell))erro();
  const v=cell.userEnteredValue;
  if(v===undefined)return '';
  if(!v||typeof v!=='object'||Array.isArray(v))erro();
  const keys=Object.keys(v);
  if(keys.length===0)return '';
  if(keys.length!==1||keys[0]!=='stringValue'||typeof v.stringValue!=='string')erro();
  return v.stringValue;
 });
}

const valores=lerCelulas($input.first().json,c);
const normalizar=l=>{const a=[...l];while(a.length&&a[a.length-1]==='')a.pop();return a;};
const atual=normalizar(valores);
const igual=(a,b)=>JSON.stringify(normalizar(a))===JSON.stringify(normalizar(b));
if(atual.some(v=>v!=='')&&!igual(atual,c.celulas)&&!c.anteriores.some(a=>igual(atual,a)))throw new Error('Conteúdo manual ou pedido divergente.');
return [{json:{...c,gravar:!igual(atual,c.celulas),values:valores.length?[valores]:[]}}];

const c=$('Planilha · Validar cabeçalho').first().json;
function lerCelulas(m,c){
 const erro=()=>{throw new Error('Linha precisa de conferência; preserve conteúdo manual.');};
 if(!m||m.spreadsheetId!==c.planilha_id||!Array.isArray(m.sheets))erro();
 const abas=m.sheets.filter(s=>s&&s.properties&&s.properties.sheetId===c.aba_id);
 if(abas.length!==1||abas[0].properties.title!=='Planejamento CRM'||!Array.isArray(abas[0].data)||abas[0].data.length!==1)erro();
 const g=abas[0].data[0];
 if(!g||(g.startRow||0)!==c.linha-1||(g.startColumn||0)!==0)erro();
 const rows=g.rowData===undefined?[]:g.rowData;
 if(!Array.isArray(rows)||rows.length>1||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))erro();
 const cells=rows[0]?.values===undefined?[]:rows[0].values;
 if(!Array.isArray(cells)||cells.length>14)erro();
 return cells.map(cell=>{
  if(!cell||typeof cell!=='object'||Array.isArray(cell))erro();
  const v=cell.userEnteredValue;
  if(v===undefined)return '';
  if(!v||typeof v!=='object'||Array.isArray(v))erro();
  const keys=Object.keys(v);
  if(keys.length===0)return '';
  if(keys.length!==1||keys[0]!=='stringValue'||typeof v.stringValue!=='string')erro();
  return v.stringValue;
 });
}

const m=$input.first().json;
const avaliada=$('Planilha · Avaliar linha').first().json;
const valores=avaliada.gravar?lerCelulas(m,c):avaliada.values?.[0];
const normalizar=l=>{const a=[...l];while(a.length&&a[a.length-1]==='')a.pop();return a;};
if(!Array.isArray(valores)||JSON.stringify(normalizar(valores))!==JSON.stringify(normalizar(c.celulas)))throw new Error('Gravação não confirmada.');
return [{json:{protocolo:1,estado:'sincronizado',planilha_id:c.planilha_id,aba_id:c.aba_id,pedido_id:c.pedido_id,envio_id:c.envio_id,linha:c.linha,revisao:c.revisao,versao:c.versao,celulas:c.celulas}}];

const v=$input.first().json;
for(const p of v.pendencias) v.evidencias.push({...p,estado:'nao_confirmado',motivo:['site','email'].includes(p.criterio)?'A coleta não comprova este critério. Verificação complementar pendente.':'Qualificador de fontes públicas pendente de configuração.',fonte:'qualificacao_pendente',horario:new Date().toISOString()});
return [{json:v}];

const r=$input.first().json;
if(!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||r.body?.instance?.state!=='open') throw new Error('Instância WhatsApp desconectada. Preserve o lote.');
return [{json:$('Preparar WhatsApp').first().json}];
